 x.rule('COUNTS_HALF_REVIEW',o(a(c('anc','>=',.5),c('anc','<=',.9)),a(c('platelets','>=',50),c('platelets','<=',99))),'consultant_review','ANC0.5–0.9 or platelets50–99×10⁹/L: NCCP Table1 lists50% treatment dose. Confirm BOTH counts and any more restrictive component rule before prescribing; this is not clearance or an automatic dose.',2,'Table1')
 x.rule('PROLONGED_COUNT_DELAY_VBL',c('delay_days','>=',14),'consultant_review','A count-related delay of≥2weeks requires reducing the BASELINE vinblastine dose by25% (to75% of baseline). This applies to vinblastine only and is not25% off an already reduced dose. Reconcile current counts and other reductions.',2,'Table1 footnote',v)
 x.rule('COUNT_RESTART_HISTORY',a(c('previous_count_delay','==',True),o(c('anc','missing'),c('platelets','missing'),c('delay_days','missing'))),'consultant_review','After a prior count delay, both current counts and the total delay duration are needed to select the restart/reduction plan.',2,'Table1',precaution=True)
 x.rule('RENAL_EXCLUSION',c('crcl_ml_min','<',30),'contraindicated','CrCl<30mL/min is a regimen exclusion and low-dose MTX product-information contraindication. NCCP organ table20–50 half-dose and dialysis exceptions must not override that exclusion; no automatic numeric dose.',1,'Exclusions versus p2Table2',m,MTX)
 x.rule('MTX_RENAL_HALF_REVIEW',a(c('crcl_ml_min','>=',30),c('crcl_ml_min','<',50)),'consultant_review','NCCP and low-dose MTX product information both support a50%-of-original-dose review in this renal range. Review actual prior dose and other toxicity; vinblastine itself requires no renal adjustment.',2,'Table2',m,MTX)
 x.rule('MTX_RENAL_SOURCE_CONFLICT',a(c('crcl_ml_min','>=',50),c('crcl_ml_min','<=',60)),'withhold','NCCP lists≥50 full dose and20–50 half dose, overlapping at50. Current HPRA low-dose MTX lists>60 full,30–59 half, leaving the59–60 boundary incompletely specified. Source prescriptions disagree in this range; withhold MTX pending consultant/pharmacy reconciliation. No inferred rounding or automatic dose.',2,'Table2 versus HPRA4.2 Table1a',m,MTX)
 x.rule('MTX_DIALYSIS_HOLD',c('haemodialysis','==',True),'withhold','MTX on haemodialysis is not recommended. NCCP exceptional high-flux/dose wording does not override the CrCl<30 regimen exclusion; specialist/pharmacy review is mandatory. Vinblastine renal dosing is a separate question.',2,'Table2',m,MTX)
 x.rule('MTX_BILIRUBIN_AVOID',c('bilirubin_umol_l','>',86),'withhold','Bilirubin>86µmol/L: NCCP says avoid methotrexate. Current HPRA contraindicates>85.5µmol/L. No numeric MTX dose.',2,'Table2',m,MTX)
 x.rule('MTX_BILIRUBIN_SOURCE_BOUNDARY',a(c('bilirubin_umol_l','>',85.5),c('bilirubin_umol_l','<=',86)),'withhold','HPRA contraindicates bilirubin>85.5µmol/L while NCCP says avoid above86. This narrow source boundary must be reviewed; do not round away a contraindication.',2,'Table2 versus HPRA4.2',m,MTX)
 x.rule('VBL_HEPATIC_SOURCE_REVIEW',o(c('bilirubin_umol_l','>',51),c('direct_bilirubin_mg_dl','>',3)),'consultant_review','NCCP lists50% of ORIGINAL vinblastine dose for bilirubin>51µmol/L without specifying analyte. HPRA specifies DIRECT bilirubin>3mg/dL. Confirm direct/total result and source interpretation; avoid assuming identical rounded cutoffs. This rule does not reduce MTX.',2,'Table2',v,VBL)
 x.rule('LARGE_THIRD_SPACE_EXCLUSION',c('large_third_space_fluid','==',True),'contraindicated','Large third-space collections are a regimen exclusion. Methotrexate can accumulate and prolong toxicity; address the fluid collection and obtain specialist review before treatment.',1,'Exclusions',m,MTX)
 x.rule('FLUID_RETENTION_REVIEW',c('significant_fluid_retention','==',True),'withhold','Clinically significant third-space fluid retention requires reconsideration of methotrexate because accumulation can delay elimination. Review collection size, drainage where appropriate and overall suitability.',3,'Table3 / complications',m,MTX,True)
 x.rule('NEUROPATHY_VBL_REVIEW',c('neuropathy_grade','>',2),'consultant_review','Grade>2 neuropathy: vinblastine reduction may be required at consultant discretion. The source does not specify a mandatory omission or numeric reduction.',3,'Table3',v)
 x.rule('MUCOSITIS_G1_MTX_REVIEW',c('mucositis_grade','==',1),'consultant_review','Grade1 mucositis: NCCP reduces MTX by50%. Assess active oral ulceration against the product-information contraindication; do not automatically prescribe50%. Vinblastine is not modified by this row.',3,'Table3',m,MTX)
 x.rule('MUCOSITIS_G2_OMIT_MTX',c('mucositis_grade','==',2),'omit','Grade2 mucositis: reduce methotrexate by100%, meaning OMIT MTX, not administer100%. No source-driven vinblastine reduction is implied.',3,'Table3',m)
 x.rule('MUCOSITIS_HIGHER_GRADE_HOLD',c('mucositis_grade','>=',3),'withhold','Severe mucositis requires withholding MTX and urgent assessment. NCCP Table3 only explicitly lists grades1 and2; no invented grade3/4 restart dose.',3,'Table3 scope boundary',m,MTX,True)
 x.rule('ORAL_GI_ULCER_MTX_HOLD',c('active_oral_or_gi_ulcer','==',True),'contraindicated','Current MTX product information contraindicates oral ulcers and known active gastrointestinal ulcer disease. Reconcile this with NCCP graded-mucositis guidance; do not issue a numeric MTX dose.',5,'SmPC4.3 Contraindications',m,MTX,primary=True)
 x.rule('MUCOSITIS_RECOVERY_REQUIRED',a(c('prior_mucositis_hold','==',True),missing_false('mucositis_recovered')),'withhold','A previous MTX mucositis hold/omission requires confirmed recovery and a reviewed restart plan. A missing recovery assessment must not trigger automatic restart.',3,'Table3 / restart safety boundary',m,precaution=True)
 x.rule('MUCOSITIS_RESTART_REVIEW',a(c('prior_mucositis_hold','==',True),c('mucositis_recovered','==',True)),'consultant_review','After mucositis recovery, confirm current grade, actual prior MTX dose, renal/hepatic findings and specialist restart plan. The source does not provide an automatic rechallenge formula.',3,'Table3 scope boundary',m,precaution=True)
 x.rule('MTX_RESPIRATORY_REVIEW',c('new_respiratory_symptoms','==',True),'discontinue','Withdraw MTX and promptly investigate pulmonary symptoms, including infection and drug-induced lung disease; this is not a numerical dose adjustment.',7,'SmPC4.4 Pulmonary toxicity',m,MTX,False,True)
 x.rule('MTX_LUNG_DISEASE_NO_RESTART',c('mtx_induced_lung_disease_suspected','==',True),'permanently_discontinue','If MTX-induced lung disease is suspected, product information says methotrexate must not be restarted. A later normal symptom score does not erase that previous no-restart decision.',7,'SmPC4.4 Pulmonary toxicity',m,MTX,False,True)
 x.rule('VBL_ILEUS_REVIEW',c('suspected_vinca_ileus','==',True),'withhold','Suspected paralytic ileus requires urgent assessment and interruption review before more vinblastine.',6,'SmPC4.8 Ileus / adverse effects',v,VBL,True,True)
 x.rule('INTERACTION_REVIEW',c('important_drug_interaction','==',True),'consultant_review','Review interacting medicines with oncology pharmacy, including MTX clearance/antifolate interactions and vinca interactions with azole antifungals. No automatic dose or routine interacting prophylaxis is inferred.',4,'Drug interactions',extra=MTX)
